import {applyImportedEvidence} from './well-data.js';
import {sourceActionTrigger,openSourceActions,closeSourceActions,downloadOriginal} from './source-actions.js';
import {importCompletion} from './well-import-ui.js';
import {suggest} from './well-data.js';
import {openWellQC} from './well-qc.js';
import {openWellImporter,sourceTextViewer} from './well-importer.js';
import {families,formatCatalog,mappingRoles,labels,visibleFamily,bytes} from './ingestion-catalog.js';
import {browserRead,loadCloud,nativeImport,commitNative,cancelNative,nativePreview,importLocal,commitLocal,pollImport,resumableUpload} from './ingestion-client.js';
import * as repository from './project-repository.js';
import {api} from './auth.js';

let lastProject=null,lastViewRoute=null,lastViewProject=null;
let host,tab='sources',query='',typeFilter='',statusFilter='',loading=false,lastCloud=0,refreshTimer;
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=value=>value===null||value===undefined?'':typeof value==='object'?JSON.stringify(value):String(value);
const short=value=>{const result=text(value);return esc(result.length>160?result.slice(0,160)+'…':result);};
const nameOf=id=>families.find(f=>f.id===id)?.name||id;
export function configureData(context){host=context;}
function context(){return host.getState().ingestion||{imports:[],datasets:[],templates:[]};}
const datasetKey=d=>`${d.importId||'science-'+d.scientificRunId}:${d.id}`;
export function dataPageView(route){
 const projectId=host.getProject()?.id;
 if(route!==lastViewRoute||projectId!==lastViewProject){
  tab=route==='wells'?'wells':'sources';
  typeFilter=route==='documents'?'documents':'';query='';statusFilter='';
  lastViewRoute=route;lastViewProject=projectId;
 }
 const state=host.getState(),project=host.getProject(),data=context();
 const wellNames=new Map((state.wellDrafts||[]).map(w=>[w.id,w.name||w.id]));for(const dataset of data.datasets||[])for(const well of dataset.wellRecords||[])if(!wellNames.has(well.id))wellNames.set(well.id,well.name||well.id);
 const wellName=id=>{const name=wellNames.get(id)||id||'';return /^[a-f0-9-]{30,}$/i.test(name)?'Well name needs review':name;};
 const matching=item=>(text(item.displayName||item.name||item.id)+' '+text(wellName(item.well))).toLowerCase().includes(query.toLowerCase())&&(!typeFilter||(item.family||item.type)===typeFilter)&&(!statusFilter||statusFilter==='Trash'&&(item.trashed===true)||(item.status||'').includes(statusFilter));
 const files=state.files||[],datasets=data.datasets||[],imports=data.imports||[];
 const active=datasets.filter(d=>d.active!==false);
 const tabs=[['sources','Sources',files.filter(f=>!f.trashed).length],['wells','Wells',(state.wellDrafts||[]).length],['datasets','Datasets',active.length],['history','Import history',imports.length]];
 let body;
 if(tab==='sources')body=table(['Original source','Data type','Well / survey','Status','Size','Actions'],files.filter(f=>statusFilter==='Trash'?f.trashed:!f.trashed).filter(matching).map(f=>`<tr><td><strong>${esc(f.displayName||f.name)}</strong><small>${f.external?'Linked external original':f.sha256?'SHA-256 verified':'Original retained'}</small></td><td>${esc(nameOf(f.type))}</td><td>${esc(f.well?wellName(f.well):'Not assigned')}</td><td>${pill(f.trashed?'In Trash':f.status||'Stored original · classification required')}</td><td class="mono">${typeof f.size==='number'?bytes(f.size):esc(f.size)}</td><td>${sourceActionTrigger(f)}</td></tr>`),'No sources yet','Add original files, then confirm their identity, mapping and references.');
 else if(tab==='datasets')body=table(['Dataset','Data type','Records','Well','Status',''],active.filter(matching).map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.parserVersion||'')} · original linked</small></td><td>${esc(nameOf(d.family))}</td><td class="mono">${Number(d.rowCount||0).toLocaleString()}</td><td>${esc(d.well?wellName(d.well):'Not assigned')}</td><td>${pill(d.status)}</td><td><button data-dataset="${esc(datasetKey(d))}">Preview</button>${['checkshots','deviation'].includes(d.family)?`<button data-well-qc="${esc(d.id)}">Observations & QC</button>`:''}</td></tr>`),'No imported datasets','Originals become datasets only after inspection and your final confirmation.');
 else if(tab==='wells')body=table(['Well identifier','Evidence','Registration state',''],(state.wellDrafts||[]).filter(w=>[w.id,w.name,w.uwi,...(w.aliases||[])].some(value=>String(value||'').toLowerCase().includes(query.toLowerCase()))).map(w=>`<tr><td><strong>${esc(w.name||w.id)}</strong><small>${esc(w.uwi||w.id)}</small></td><td>${datasets.filter(d=>d.well===w.id).length} datasets</td><td>${pill(w.status)}</td><td><button data-well-evidence="${esc(w.id)}">View evidence</button></td></tr>`),'No wells registered','Confirm well identities while importing logs, headers or survey evidence.');
 else body=table(['Import','Data type','Sources','State',''],imports.filter(matching).map(r=>`<tr><td><strong>${esc(new Date(r.createdAt).toLocaleString())}</strong><small>${esc(r.id.slice(0,16))}</small></td><td>${esc(nameOf(r.family))}</td><td>${r.assets?.length||0}</td><td>${pill(r.status)}</td><td><button data-import="${esc(r.id)}">${['inspecting','importing','uploading'].includes(r.status)?'View progress':'Review'}</button></td></tr>`),'Your import history starts here','Completed imports, warnings and retained originals stay traceable.');
 return `<section class="data-library"><div class="data-page-head"><div><div class="study-kicker">PROJECT EVIDENCE</div><h1>Data</h1><p>Keep the originals. Confirm the meaning. Import with confidence.</p></div><div class="actions"><button id="data-formats">Supported formats</button><button class="primary" data-action="upload">${host.icon('plus')}Add data</button></div></div><div class="data-summary"><span><strong>${files.filter(f=>!f.trashed).length}</strong> originals</span><span><strong>${active.length}</strong> datasets</span><span><strong>${active.filter(d=>d.status==='retained/unresolved').length}</strong> need reference review</span><span>${project.storage==='cloud'?'Cloud storage':project.storage==='local'?'Local folder':'Portable project'}${data.quota?` · ${bytes(data.quota.used)} / ${bytes(data.quota.projectLimit)}`:''}</span></div><div class="data-surface"><nav class="data-tabs" aria-label="Data sections">${tabs.map(([id,title,count])=>`<button data-data-section="${id}" aria-current="${id===tab?'page':'false'}">${title}<span>${count}</span></button>`).join('')}</nav><div class="data-filter-bar"><label class="data-search">${host.icon('search')}<input id="data-query" aria-label="Search project data" placeholder="Search by name or well…" value="${esc(query)}"></label>${tab!=='wells'?`<select id="data-type-filter" aria-label="Filter data type"><option value="">All data types</option>${families.map(f=>`<option value="${f.id}" ${typeFilter===f.id?'selected':''}>${f.name}</option>`).join('')}</select><select id="data-status-filter" aria-label="Filter import status"><option value="">All states</option>${['ready','retained','awaiting','failed','cancelled','inspecting',...(tab==='sources'?['Trash']:[])].map(v=>`<option ${statusFilter===v?'selected':''}>${v}</option>`).join('')}</select>`:''}<button id="refresh-data" class="quiet">${loading?'Refreshing…':'Refresh'}</button></div>${body}</div><p class="data-footnote">Ready means imported—not scientifically approved. Unconfirmed units, coordinates and datums remain visible.</p></section>`;
}
function table(headers,rows,title,description){const filtered=!!(query||typeFilter||statusFilter)&&((host.getState().files||[]).length+(context().datasets||[]).length+(host.getState().wellDrafts||[]).length)>0;return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:`<div class="data-empty"><span>${host.icon('file')}</span><h2>${filtered?'No matching data':title}</h2><p>${filtered?'Your saved data is still here. Change or clear the filters to see it.':description}</p>${filtered?'<button id="clear-data-filters">Clear filters</button>':`<button data-action="upload">Add data ${host.icon('arrow')}</button>`}</div>`;}
function pill(status){return `<span class="data-status ${/failed|blocking/.test(status)?'failed':/ready/.test(status)?'ready':'neutral'}">${esc(status||'Not classified')}</span>`;}
export function bindDataPage(){closeSourceActions();if(lastProject!==host.getProject()?.id){lastProject=host.getProject()?.id;lastCloud=0;}
 document.querySelectorAll('[data-data-section]').forEach(b=>b.onclick=()=>{tab=b.dataset.dataSection;if(statusFilter==='Trash'&&tab!=='sources')statusFilter='';host.render();});
 $('#data-query')?.addEventListener('input',e=>{query=e.target.value;const position=e.target.selectionStart;host.render();$('#data-query').focus();$('#data-query').setSelectionRange(position,position);});
 $('#data-type-filter')?.addEventListener('change',e=>{typeFilter=e.target.value;host.render();});$('#data-status-filter')?.addEventListener('change',e=>{statusFilter=e.target.value;host.render();});
 $('#clear-data-filters')?.addEventListener('click',()=>{query='';typeFilter='';statusFilter='';host.render();});
 $('#data-formats')?.addEventListener('click',()=>host.modal('Format coverage',`<p class="sub">Coverage depends on the documented version and selected storage. Closed variants require conversion; no format is accepted by extension alone.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Format</th><th>Versions / boundaries</th><th>Cloud</th><th>Local</th></tr></thead><tbody>${formatCatalog.map(f=>`<tr><td>${esc(f.name)}</td><td>${esc(f.versions)}</td><td>${esc(f.server)}</td><td>${esc(f.local)}</td></tr>`).join('')}</tbody></table></div>`));
 $('#refresh-data')?.addEventListener('click',()=>refreshData(true));
 document.querySelectorAll('[data-source-actions]').forEach(button=>button.onclick=()=>{const file=host.getState().files.find(f=>(f.id||f.name)===button.dataset.sourceActions);if(file)openSourceActions(host,file,button,{inspect:f=>sourceDetail(f.id||f.name),reclassify:f=>openImporter({existing:f,family:families.some(category=>category.id===f.type)?f.type:undefined})});});
 document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>sourceDetail(b.dataset.source));
 document.querySelectorAll('[data-dataset]').forEach(b=>b.onclick=()=>datasetDetail(b.dataset.dataset));
 document.querySelectorAll('[data-well-qc]').forEach(b=>b.onclick=()=>openWellQC(host,context().datasets.find(d=>d.id===b.dataset.wellQc)).catch(e=>host.toast(e.message)));
 document.querySelectorAll('[data-import]').forEach(b=>b.onclick=()=>reviewImport(b.dataset.import));
 document.querySelectorAll('[data-well-evidence]').forEach(b=>b.onclick=()=>{query=b.dataset.wellEvidence;tab='datasets';host.render();});
 if(host.getProject()?.storage==='cloud'&&Date.now()-lastCloud>10000&&!loading)refreshData();
}
async function refreshData(force=false){
 const project=host.getProject();if(!project||project.storage!=='cloud')return;
 loading=true;try{const data=await loadCloud(project);if(host.getProject()?.id!==project.id)return;applyImportedEvidence(host.getState(),data);lastCloud=Date.now();loading=false;host.render();if(data.imports.some(r=>['inspecting','importing'].includes(r.status))){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>refreshData(),5000);}}catch(error){host.toast(error.message);}finally{loading=false;}
}
async function sourceDetail(id){
 const source=host.getState().files.find(f=>(f.id||f.name)===id);if(!source)return;
 host.modal('Original source',`<h3>${esc(source.displayName||source.name)}</h3><dl class="data-details"><dt>Original filename</dt><dd>${esc(source.name)}</dd><dt>Size</dt><dd>${typeof source.size==='number'?bytes(source.size):esc(source.size)}</dd><dt>Storage</dt><dd>${source.external?'Linked external file':'Retained original'}</dd><dt>Fingerprint</dt><dd class="mono">${esc(source.sha256||'Computed during inspection')}</dd><dt>Status</dt><dd>${esc(source.status||'Classification required')}</dd></dl><div class="actions"><button id="source-text">View complete source</button><button id="source-download">Download original</button><button id="source-classify" class="primary">Import / classify</button></div>`);
 $('#source-download').onclick=()=>downloadOriginal(host,source).catch(error=>host.toast(error.message));
 $('#source-text').onclick=async()=>{try{if(/\.(dlis|lis|xlsx|xls|pdf|docx|png|jpg|segy|sgy)$/i.test(source.name))throw new Error('Use the structured dataset preview or download this binary original.');if(source.size>128*1024**2&&host.getProject().storage==='cloud')throw new Error('Download this large original for local text inspection.');await sourceTextViewer(host,new File([await repository.source(host.getProject(),source)],source.name));}catch(e){host.toast(e.message);}};
 $('#source-classify').onclick=()=>{ $('#dialog').close();openImporter({existing:source});};
}
function previewTable(dataset){return `<div class="data-preview-meta"><span>${dataset.rowCount.toLocaleString()} records</span><span>${dataset.columns.length} columns</span><span>${esc(dataset.metadata?.format||'')}</span></div><div class="table-wrap data-preview"><table><thead><tr>${dataset.columns.slice(0,16).map(c=>`<th>${esc(c.mnemonic)}<small>${esc(c.effectiveUnit||c.unit||'Unit unconfirmed')}</small></th>`).join('')}</tr></thead><tbody>${dataset.preview.slice(0,30).map(row=>`<tr>${row.slice(0,16).map(v=>`<td>${short(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${curvePlot(dataset)}<details class="source-metadata"><summary>Source metadata and references</summary><pre>${esc(JSON.stringify(dataset.metadata||{},null,2))}</pre></details>`;}
function curvePlot(dataset){if(dataset.columns.length<2||dataset.family!=='logs')return '';const data=dataset.preview.filter(row=>typeof row[0]==='number'&&typeof row[1]==='number');if(data.length<2)return '';const xs=data.map(r=>r[1]),ys=data.map(r=>r[0]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);const pts=data.map(r=>`${40+(r[1]-xmin)/(xmax-xmin||1)*500},${20+(r[0]-ymin)/(ymax-ymin||1)*180}`).join(' ');return `<div class="data-curve"><p>Source preview · ${esc(dataset.columns[1].mnemonic)} against ${esc(dataset.columns[0].mnemonic)} · first ${data.length} valid samples</p><svg viewBox="0 0 580 230" role="img" aria-label="Imported source curve preview"><path d="M40 15v185h510" stroke="#a8b9b1" fill="none"/><polyline points="${pts}" stroke="#087c73" stroke-width="1.6" fill="none"/><text x="40" y="220">${xmin}</text><text x="480" y="220">${xmax}</text></svg></div>`;}
async function datasetDetail(key){const [importId,id]=key.split(':');const dataset=context().datasets.find(d=>d.id===id&&(d.importId===importId||'science-'+d.scientificRunId===importId));if(!dataset)return;try{const result=host.getProject().storage==='cloud'?await (dataset.scientificRunId?api(`/api/projects/${host.getProject().id}/science/datasets/${id}/rows?limit=2000`).then(r=>({...r,preview:r.rows})):nativePreview(host.getProject(),importId,id)):dataset;if(dataset.activeColumns){const indices=result.columns.map((c,i)=>dataset.activeColumns.includes(c.id)?i:-1).filter(i=>i>=0);result.columns=indices.map(i=>result.columns[i]);result.preview=result.preview.map(row=>indices.map(i=>row[i]));}host.modal('Dataset preview',`<h3>${esc(dataset.name)}</h3><p class="sub">Imported evidence · scientific approval has not been granted.</p>${previewTable(result)}${issuesView(dataset.issues||[])}`);}catch(error){host.toast(error.message);}}
function issuesView(issues){return issues.length?`<div class="import-issues">${issues.slice(0,80).map(i=>`<div class="import-issue ${i.severity==='blocking'?'blocking':''}"><strong>${i.severity==='blocking'?'Resolve before activation':'Review'}</strong><p>${esc(i.message)}</p></div>`).join('')}</div>`:'<div class="import-clear">No import validation issues found. Scientific review is separate.</div>';}

export async function openImporter(options={}){return openWellImporter(host,options,record=>{if(!context().imports.some(r=>r.id===record.id))context().imports.unshift(record);return reviewImport(record.id);});}
function recordView(record){const blocking=(record.issues||[]).some(i=>i.severity==='blocking'&&!i.sourceId&&!i.source)||!(record.datasets||[]).some(d=>!d.issues?.some(i=>i.severity==='blocking'));return `<div class="import-result-head">${pill(record.status)}<span>${record.datasets?.length||0} datasets found</span></div>${issuesView(record.issues||[])}<div class="import-dataset-list">${(record.datasets||[]).map(d=>`<label class="layer"><input type="checkbox" data-select-dataset="${esc(d.id)}" ${d.issues?.some(i=>i.severity==='blocking')?'':'checked'}>Include dataset</label><button type="button" data-review-dataset="${esc(d.id)}"><span><strong>${esc(d.name)}</strong><small>${Number(d.rowCount||0).toLocaleString()} records · ${d.columns?.length||0} columns</small></span>Preview →</button>`).join('')}</div>${!record.committedAt&&['awaiting confirmation','retained/unresolved'].includes(record.status)?`<label class="layer"><input type="checkbox" id="ack-import-warnings">I reviewed the remaining warnings. Imported data is not scientifically approved.</label><label class="field">Save mapping template <small>Optional</small><input id="import-template-name" maxlength="100" placeholder="For example: deviation survey export"></label><button type="button" class="primary" id="commit-import" ${blocking?'disabled':''}>Confirm import</button>${blocking?'<p class="sub">Originals are retained. Resolve the blocking format or mapping issues before activation.</p>':''}`:''}`;}
function bindRecordActions(record,project,onComplete){
 const commitButton=$('#commit-import');
 if(commitButton){
  const previous=(context().datasets||[]).filter(d=>d.active!==false);
  if(previous.length){const field=document.createElement('label');field.className='field';field.innerHTML='Version handling<select id="import-replace"><option value="">Create independent datasets (recommended)</option>'+previous.map(d=>'<option value="'+esc(d.id)+'">Replace active: '+esc(d.name)+'</option>').join('')+'</select><small>Replacement preserves the previous version. Select one new dataset.</small>';commitButton.before(field);}
  if(project.storage==='cloud'){const edit=document.createElement('button');edit.type='button';edit.textContent='Edit mapping / references';edit.onclick=()=>editNativeMapping(record,project);commitButton.before(edit);}
 }
 $('#commit-import')?.addEventListener('click',async()=>{try{if(record.issues?.length&&!$('#ack-import-warnings').checked)throw new Error('Acknowledge the remaining warnings before confirming.');$('#commit-import').disabled=true;const name=$('#import-template-name').value.trim(),replaceId=$('#import-replace')?.value||null;const selection={selected_dataset_ids:[...document.querySelectorAll('[data-select-dataset]:checked')].map(e=>e.dataset.selectDataset),selected_columns:{}};document.querySelectorAll('[data-select-column]').forEach(input=>{const id=input.dataset.columnDataset;selection.selected_columns[id]||=[];if(input.checked)selection.selected_columns[id].push(input.dataset.selectColumn);});if(project.storage==='cloud'){Object.assign(record,await commitNative(project,record,true,name,replaceId,selection));await host.reload();await refreshData(true);}else Object.assign(record,await commitLocal(host.getState(),record,{templateName:name,replaceId,selection,onSave:async()=>{host.save();await host.flush();}}));onComplete();}catch(error){host.toast(error.message);if($('#commit-import'))$('#commit-import').disabled=false;}});
 document.querySelectorAll('[data-review-dataset]').forEach(button=>button.onclick=async()=>{try{const d=record.datasets.find(d=>d.id===button.dataset.reviewDataset),preview=project.storage==='cloud'?await nativePreview(project,record.id,d.id):d;const panel=document.createElement('section');panel.className='inline-dataset-preview';panel.innerHTML='<h3>'+esc(d.name)+'</h3>'+previewTable(preview)+'<details><summary>Select active columns / channels</summary>'+preview.columns.map(c=>'<label class="layer"><input type="checkbox" data-select-column="'+esc(c.id)+'" data-column-dataset="'+esc(d.id)+'" checked>'+esc(c.mnemonic)+' · '+esc(c.effectiveUnit||c.unit||'unit unconfirmed')+'</label>').join('')+'</details>';button.after(panel);button.disabled=true;}catch(error){host.toast(error.message);}});
}
async function editNativeMapping(record,project,assetKey){
 try{const asset=record.assets.find(a=>a.clientId===assetKey||a.id===assetKey)||record.assets[0],dataset=record.datasets?.find(d=>d.assetKey===(asset.clientId||asset.id)||d.sourceId===asset.id),preview=dataset?await nativePreview(project,record.id,dataset.id):{columns:[],preview:[]},root=structuredClone(record.options||{}),key=asset.clientId||asset.id,family=asset.family||record.family,options=suggest(preview,family,structuredClone(root.perAsset?.[key]||root.perFile?.[asset.name]||root)),refs=options.references||{},mapping=options.mapping||{};
  const field=(name,label,value='')=>`<label class="field">${esc(label)}<input name="${esc(name)}" value="${esc(value)}"></label>`;
  host.modal('Review retained source',`<p>Each asset retains its own classification and associations. Reinspection reuses originals.</p><label class="field">Source asset<select id="native-asset">${record.assets.map(a=>`<option value="${esc(a.clientId||a.id)}" ${a===asset?'selected':''}>${esc(a.name)} · ${esc(a.clientId||a.id)}</option>`).join('')}</select></label>${previewTable(preview)}<details><summary>Structured source metadata</summary><pre>${esc(JSON.stringify(preview.metadata||{},null,2))}</pre></details><form id="native-mapping"><label class="field">Data category<select name="family">${families.filter(f=>visibleFamily(f,project)).map(f=>`<option value="${f.id}" ${family===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label><div class="form-grid">${(mappingRoles[family]||[]).map(role=>`<label class="field">${esc(labels[role]||role)}<select name="mapping:${esc(role)}"><option value="">Unconfirmed</option>${preview.columns.map((c,i)=>`<option value="${i}" ${String(mapping[role])===String(i)?'selected':''}>${esc(c.mnemonic)} · ${esc(c.unit||'unit unknown')}</option>`).join('')}</select></label>`).join('')}${['depthReference','depthUnit','depthSign','northReference','angleUnit','timeConvention','timeUnit','timeSign','timeDatum','verticalDatum','crs','coordinateOrder','domain','northCorrection','declination'].map(k=>field('ref:'+k,k,refs[k])).join('')}${field('well','Default owning well ID',options.well||dataset?.well)}${field('wellName','Source well name',options.wellName)}${field('surveyMethod','Survey representation: angles / offsets / xy_tvd / coordinates',options.surveyMethod)}${field('hdfPaths','HDF5 dataset paths',(options.hdfPaths||[]).join(','))}${field('frames','Frame names (blank = all)',(options.frames||[]).join(','))}</div><details open><summary>Inspected dataset associations</summary>${record.datasets.filter(d=>d.assetKey===key||d.sourceId===asset.id).map(d=>{const raw=d.metadata?.well||d.well,list=[...(host.getState().wellDrafts||[]),...record.datasets.flatMap(item=>item.wellRecords||[])].filter((w,i,all)=>all.findIndex(v=>v.id===w.id)===i);return `<label class="field">${esc(d.name)} / ${esc(raw)}<select name="binding:${esc(raw)}"><option value="">Resolve association</option>${list.map(w=>`<option value="${esc(w.id)}" ${w.id===(options.wellBindings?.[raw]||d.well)?'selected':''}>${esc(w.name||w.id)} / ${esc(w.uwi||w.id)}</option>`).join('')}</select></label>`;}).join('')}</details><details><summary>Row associations and duplicate decisions</summary><p>Use stable registered well IDs. Header actions use zero-based source rows and explicit keep, skip or merge.</p><label class="field">Row well bindings (JSON)<textarea name="wellBindings">${esc(JSON.stringify(options.wellBindings||{},null,2))}</textarea></label><label class="field">Header row actions (JSON)<textarea name="headerActions">${esc(JSON.stringify(options.headerActions||{},null,2))}</textarea></label></details><details><summary>Column units</summary>${preview.columns.map((c,i)=>field('unit:'+i,c.mnemonic+' · '+(c.unit||'unresolved'),options.units?.[i])).join('')}</details><p id="native-mapping-error" role="alert"></p><button class="primary">Save & reinspect selected source</button></form>`);
  $('#native-asset').onchange=e=>editNativeMapping(record,project,e.target.value);
  $('#native-mapping').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;try{const values=new FormData(form);options.references||={};options.mapping||={};options.units||={};for(const [name,value]of values){if(name.startsWith('ref:'))options.references[name.slice(4)]=String(value).trim();if(name.startsWith('mapping:'))options.mapping[name.slice(8)]=String(value);if(name.startsWith('unit:'))options.units[name.slice(5)]=String(value).trim();}for(const name of ['family','well','wellName','surveyMethod'])options[name]=String(values.get(name)||'');for(const name of ['frames','hdfPaths'])options[name]=String(values.get(name)||'').split(',').map(v=>v.trim()).filter(Boolean);for(const name of ['wellBindings','headerActions']){const parsed=JSON.parse(values.get(name)||'{}');if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw new Error('Enter an object for '+name);options[name]=parsed;}for(const [name,value]of values)if(name.startsWith('binding:'))options.wellBindings[name.slice(8)]=String(value);root.perAsset||={};root.perAsset[key]=options;await api(`/api/projects/${project.id}/imports/${record.id}/configuration`,{method:'PUT',body:{revision:record.revision,options:root}});await api(`/api/projects/${project.id}/imports/${record.id}/inspect`,{method:'POST',body:{}});$('#dialog').close();await refreshData(true);host.toast('Reinspection started. Follow progress in Import history.');}catch(error){$('#native-mapping-error').textContent=error.message;button.disabled=false;}};
 }catch(error){host.toast(error.message);}
}
async function reviewImport(id){let record=context().imports.find(r=>r.id===id);if(!record)return;const project=host.getProject();host.modal('Import details',`<h3>${esc(nameOf(record.family))}</h3>${recordView(record)}${['stored','failed'].includes(record.status)?'<button id="retry-inspection">Retry native inspection</button>':''}${record.status==='uploading'?`<p class="sub">Reselect each original by its asset identity to resume.</p>${record.assets.filter(a=>a.state!=='stored').map(a=>`<label class="field">${esc(a.name)} · ${esc(a.clientId||a.id)}<input data-resume-asset="${esc(a.clientId||a.id)}" type="file"></label>`).join('')}<button id="resume-import-files">Resume selected assets</button>`:''}${!record.committedAt&&record.status!=='cancelled'?'<button id="cancel-stored-import">Cancel import · keep retained originals</button>':''}`);bindRecordActions(record,project,()=>{showImportCompletion(record,project);host.render();});$('#retry-inspection')?.addEventListener('click',async()=>{try{await api(`/api/projects/${project.id}/imports/${record.id}/inspect`,{method:'POST',body:{}});await refreshData(true);host.toast('Inspection started. Reopen Import history to check progress.');$('#dialog').close();}catch(error){host.toast(error.message);}});$('#resume-import-files')?.addEventListener('click',async e=>{try{for(const asset of record.assets.filter(a=>a.state!=='stored')){const file=[...document.querySelectorAll('[data-resume-asset]')].find(input=>input.dataset.resumeAsset===(asset.clientId||asset.id))?.files?.[0];if(!file||file.name!==asset.name||file.size!==asset.size)throw new Error('Select the same file name and size for every incomplete source.');const transfer=await api(`/api/projects/${project.id}/imports/${record.id}/upload/${asset.id}`,{method:'POST',body:{}});if(!transfer.stored)await resumableUpload(file,transfer.upload_url);await api(`/api/projects/${project.id}/imports/${record.id}/complete/${asset.id}`,{method:'POST',body:{}});}await api(`/api/projects/${project.id}/imports/${record.id}/inspect`,{method:'POST',body:{}});await refreshData(true);$('#dialog').close();}catch(error){host.toast(error.message);}});$('#cancel-stored-import')?.addEventListener('click',async()=>{try{if(project.storage==='cloud')await cancelNative(project,record.id);else{record.status='cancelled';host.save();await host.flush();}await refreshData(true);$('#dialog').close();host.render();}catch(error){host.toast(error.message);}});}

function showImportCompletion(record,project){host.modal('Import complete',`<div class="ie-main"><div class="ie-content">${importCompletion({record,project,assets:record.assets.map(a=>({id:a.clientId||a.id,file:{name:a.name,size:a.size}}))})}</div></div>`);document.querySelector('#dialog').classList.add('import-evidence-dialog');document.querySelector('#wi-done')?.addEventListener('click',()=>document.querySelector('#dialog').close());document.querySelector('#wi-view-data')?.addEventListener('click',()=>{document.querySelector('#dialog').close();host.navigate('data');});}
